import{_ as t,c as a,o as r,ag as n}from"./chunks/framework.Vyheyqg9.js";const f=JSON.parse('{"title":"Retention, Expiry and Enforced Deletion — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/retention-and-deletion.md","filePath":"practice/node-js/retention-and-deletion.md"}'),o={name:"practice/node-js/retention-and-deletion.md"};function i(s,e,c,l,d,p){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="retention-expiry-and-enforced-deletion-—-practice" tabindex="-1">Retention, Expiry and Enforced Deletion — practice <a class="header-anchor" href="#retention-expiry-and-enforced-deletion-—-practice" aria-label="Permalink to “Retention, Expiry and Enforced Deletion — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These tasks were separated from the textbook; no completion is credited.</p><p><a href="./../../node-js/retention-and-deletion.html">Textbook explanation</a> · <a href="./">Node.js practice map</a></p><h2 id="practice-and-acceptance" tabindex="-1"><span class="hub-section-number">1 </span>Practice and acceptance <a class="header-anchor" href="#practice-and-acceptance" aria-label="Permalink to “1 Practice and acceptance”">​</a></h2><p>Use actual PostgreSQL16 in a new private temporary cluster and a disposable owned directory. Seed expired/at-boundary/future/held rows for all four classes, including token hashes/synthetic logs and upload bytes. Execute the exact sweep: only eligible rows/files disappear, future/held content remains, and an expired held session still fails the read-time expiry predicate. Test batch limit, two workers with a locked row/SKIP LOCKED, later retry, already-missing file, rejected path metadata, storage permission/type failure, DB rollback and pool release. Delete only scratch fixtures; stop the cluster and close all clients afterward.</p><p>Run a second sweep after simulated unlink-before-commit failure and require idempotent completion without touching an unrelated file. Retain evidence of actual physical deletion and metadata state; a fake delete callback alone is insufficient. For a real app also test authenticated retrieval after expiry, authorized hold/deletion workflows, derivative invalidation, scheduling/shutdown, backup restoration and object-store/provider failure. <strong>Learner practice and production retention compliance are not established by this local fixture.</strong></p><p>References checked2026-10-25: <a href="https://www.postgresql.org/docs/16/sql-select.html" target="_blank" rel="noreferrer">PostgreSQL16 row locking/SKIP LOCKED</a>, <a href="https://nodejs.org/download/release/v24.18.0/docs/api/fs.html#fspromisesunlinkpath" target="_blank" rel="noreferrer">Node24 unlink</a>, <a href="https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html#disposal-of-logs" target="_blank" rel="noreferrer">OWASP log disposal/access</a>, <a href="./../../node-js/module-10-production-ready-applications.html#_9-graceful-shutdown">owned jobs/shutdown</a>. Durations and schema above are declared teaching choices; verify the real product&#39;s policy separately.</p>',7)])])}const u=t(o,[["render",i]]);export{f as __pageData,u as default};
